<script>
import mpx, { createPage } from '@mpxjs/core'

createPage({
  data: {
    memberId: 'member-10086',
    activeStatus: 'all',
    statusTabs: [
      { key: 'all', label: '全部', count: 0 },
      { key: 'paying', label: '待付款', count: 1 },
      { key: 'shipping', label: '待收货', count: 2 },
      { key: 'done', label: '已完成', count: 0 }
    ],
    orders: [
      {
        id: 'order-20260812001',
        orderNo: '20260812001',
        status: 'shipping',
        statusText: '运输中',
        logisticsText: '包裹已到达上海转运中心',
        updatedAt: '今天 10:26',
        cover: '/assets/orders/blueberry.png',
        title: '云南高山蓝莓 4 盒装',
        skuText: '125g × 4 盒',
        amount: '39.90',
        count: 1,
        locked: false
      },
      {
        id: 'order-20260811008',
        orderNo: '20260811008',
        status: 'shipping',
        statusText: '已揽收',
        logisticsText: '快递员已揽收',
        updatedAt: '昨天 18:42',
        cover: '/assets/orders/coffee.png',
        title: '便携式手冲咖啡套装',
        skuText: '黑色 · 标准版',
        amount: '129.00',
        count: 1,
        locked: false
      }
    ],
    openOrderId: '',
    logisticsOnline: false,
    loading: false
  },
  onUnload () {
    this._requestGeneration = (this._requestGeneration || 0) + 1
    if (this._orderRequest && typeof this._orderRequest.abort === 'function') {
      this._orderRequest.abort()
    }
    this._orderRequest = null
  },
  methods: {
    switchStatus (status) {
      if (status === this.activeStatus) return
      this.activeStatus = status
      this.openOrderId = ''
      this.fetchOrders()
    },
    fetchOrders () {
      const status = this.activeStatus
      const generation = (this._requestGeneration || 0) + 1
      this._requestGeneration = generation

      if (this._orderRequest && typeof this._orderRequest.abort === 'function') {
        this._orderRequest.abort()
      }

      this.loading = true
      this._orderRequest = mpx.request({
        url: '/api/orders',
        data: { status },
        usePromise: false,
        success: ({ data }) => {
          if (this._requestGeneration !== generation || this.activeStatus !== status) return
          this.orders = data.list
          this.statusTabs = data.summary
          this.openOrderId = ''
        },
        complete: () => {
          if (this._requestGeneration !== generation) return
          this._orderRequest = null
          this.loading = false
        }
      })
    },
    findEnabledOrder (orderId) {
      return this.orders.find(order => order.id === orderId && !order.locked)
    },
    openOrder ({ detail }) {
      if (!this.findEnabledOrder(detail.orderId)) return
      mpx.navigateTo({ url: `/pages/orders/detail?id=${detail.orderId}` })
    },
    removeOrder ({ detail }) {
      if (!this.findEnabledOrder(detail.orderId)) return
      mpx.showModal({
        title: '删除订单',
        content: '删除后将无法在订单列表中查看，确认删除吗？',
        usePromise: false,
        success: ({ confirm }) => {
          if (!confirm || !this.findEnabledOrder(detail.orderId)) return
          mpx.request({
            url: `/api/orders/${detail.orderId}`,
            method: 'DELETE',
            usePromise: false,
            success: () => {
              this.orders = this.orders.filter(order => order.id !== detail.orderId)
              if (this.openOrderId === detail.orderId) this.openOrderId = ''
            }
          })
        }
      })
    },
    handleSwipeStart ({ detail }) {
      if (!this.findEnabledOrder(detail.orderId)) return
      if (this.openOrderId && this.openOrderId !== detail.orderId) {
        this.openOrderId = ''
      }
    },
    handleSwipeEnd ({ detail }) {
      if (!this.findEnabledOrder(detail.orderId)) return
      if (detail.open) {
        this.openOrderId = detail.orderId
      } else if (this.openOrderId === detail.orderId) {
        this.openOrderId = ''
      }
    },
    handleConnectionChange ({ detail }) {
      this.logisticsOnline = detail.connected
    },
    handleLogisticsMessage ({ detail }) {
      this.orders = this.orders.map(order => {
        if (order.id !== detail.orderId) return order
        return Object.assign({}, order, {
          status: detail.status,
          statusText: detail.statusText,
          logisticsText: detail.logisticsText,
          updatedAt: detail.updatedAt
        })
      })
    },
    handleChannelError () {
      this.logisticsOnline = false
    },
    goShopping () {
      mpx.switchTab({ url: '/pages/home/index' })
    }
  }
})
</script>

